create table public.audit_logs(id bigint generated always as identity primary key,actor_id uuid,actor_role text,event_type text not null,resource text,summary text,created_at timestamptz not null default now());
create table public.platform_settings(key text primary key,value text not null,updated_at timestamptz not null default now());
create table public.mission_overrides(id integer generated by default as identity(start with 19) primary key,data jsonb not null);
alter table public.audit_logs enable row level security;
alter table public.platform_settings enable row level security;
alter table public.mission_overrides enable row level security;
revoke all on public.audit_logs,public.platform_settings,public.mission_overrides from anon,authenticated;
grant select on public.mission_overrides to authenticated;
grant select on public.audit_logs to authenticated;
grant select,insert,update on public.platform_settings to authenticated;
grant insert,update on public.mission_overrides to authenticated;
grant usage on sequence public.mission_overrides_id_seq to authenticated;
create policy audit_admin_read on public.audit_logs for select to authenticated using(public.current_app_role()='admin');
create policy settings_admin on public.platform_settings for all to authenticated using(public.current_app_role()='admin') with check(public.current_app_role()='admin');
create policy overrides_read on public.mission_overrides for select to authenticated using(public.current_app_role()='admin' or (coalesce((data->>'isPublished')::boolean,false) and not coalesce((data->>'isArchived')::boolean,false)));
create policy overrides_insert on public.mission_overrides for insert to authenticated with check(public.current_app_role()='admin');
create policy overrides_update on public.mission_overrides for update to authenticated using(public.current_app_role()='admin') with check(public.current_app_role()='admin');
create function public.audit_admin_change() returns trigger language plpgsql security definer set search_path='' as $$ begin
 insert into public.audit_logs(actor_id,actor_role,event_type,resource,summary) values(auth.uid(),public.current_app_role(),lower(TG_OP),TG_TABLE_NAME,'Administrator updated '||TG_TABLE_NAME);
 return new; end; $$;
revoke all on function public.audit_admin_change() from public;
create trigger settings_audit after insert or update on public.platform_settings for each row execute function public.audit_admin_change();
create trigger missions_audit after insert or update on public.mission_overrides for each row execute function public.audit_admin_change();
create function public.admin_update_account(p_user uuid,p_role text default null,p_status text default null) returns void language plpgsql security definer set search_path='' as $$
begin
 perform pg_advisory_xact_lock(11223344);
 if public.current_app_role() is distinct from 'admin' then raise exception 'Administrator access required'; end if;
 if p_role is not null and p_role not in ('student','instructor','admin') then raise exception 'Invalid role'; end if;
 if p_status is not null and p_status not in ('active','suspended') then raise exception 'Invalid status'; end if;
 if p_user=auth.uid() then raise exception 'Use another administrator to change your own account'; end if;
 update public.profiles set role=coalesce(p_role,role),account_status=coalesce(p_status,account_status) where id=p_user;
 if not found then raise exception 'Account not found'; end if;
 insert into public.audit_logs(actor_id,actor_role,event_type,resource,summary) values(auth.uid(),'admin','account_updated',p_user::text,'Updated account role or status');
end; $$;
revoke all on function public.admin_update_account(uuid,text,text) from public;
grant execute on function public.admin_update_account(uuid,text,text) to authenticated;
